import{c as e,Q as o,j as a,m as n}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"Automation — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"automation/overview.md","filePath":"automation/overview.md","lastUpdated":null}'),r={name:"automation/overview.md"};function i(s,t,l,d,h,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="automation-—-overview" tabindex="-1">Automation — Overview <a class="header-anchor" href="#automation-—-overview" aria-label="Permalink to &quot;Automation — Overview&quot;">​</a></h1><p>FinSight automates the repetitive parts and leaves the decisions with you.</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Trigger</th><th>Review</th></tr></thead><tbody><tr><td><strong>Rules</strong> — pattern &amp; treatment</td><td>Incoming transactions</td><td>Enable/disable; counts shown</td></tr><tr><td><strong>Categorization</strong> — LLM + deterministic fallbacks</td><td>Uncategorized queue</td><td>Confidence; needs-review filter</td></tr><tr><td><strong>Recipes</strong> — trusted multi-step bundles</td><td>You do</td><td>Plan shown; confirm once</td></tr></tbody></table><p>All three are deterministic first, LLM second, and never silent — you see the proposal and the effect before it lands.</p><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Choosing&quot;">​</a></h2><ul><li>Use a <strong>rule</strong> when the same merchant should always get the same category/treatment.</li><li>Trust <strong>categorization</strong> for the long tail where no rule exists — the Copilot explains low-confidence calls.</li><li>Run a <strong>recipe</strong> for one-off, multi-step housekeeping (e.g. “Create next month’s envelopes from actuals”).</li></ul><p>Next: <a href="/FinSight/automation/rules">Rules</a>.</p>',7)])])}const p=e(r,[["render",i]]);export{m as __pageData,p as default};
